CREATE OR REPLACE FUNCTION public.create_verified_adhesion(p_protest_id uuid, p_identity_subject_hash text, p_verification_method text, p_nullifier text, p_device_id text, p_doc_hash text, p_ciudad text, p_region text, p_pais text, p_pais_code text, p_idioma text, p_adhesion_osm_id bigint, p_gps_confirmed boolean, p_fiabilidad integer, p_senales text, p_institutional_email_hash text, p_institutional_expires_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_protest       record;
  v_adhesion_id   uuid;
  v_created_at    timestamptz;
BEGIN
  SELECT id, ends_at, saldo_euros
    INTO v_protest
    FROM protests
    WHERE id = p_protest_id
    FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'VP_PROTEST_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;

  IF v_protest.ends_at < now() THEN
    RAISE EXCEPTION 'VP_PROTEST_CLOSED' USING ERRCODE = 'P0001';
  END IF;

  IF v_protest.saldo_euros IS NOT NULL AND v_protest.saldo_euros <= 0 THEN
    RAISE EXCEPTION 'VP_BALANCE_EXHAUSTED' USING ERRCODE = 'P0001';
  END IF;

  BEGIN
    IF p_institutional_email_hash IS NOT NULL THEN
      INSERT INTO institutional_members (email_hash, protest_id, expires_at)
      VALUES (p_institutional_email_hash, p_protest_id, p_institutional_expires_at);
    END IF;

    v_created_at := date_trunc('hour', now());

    IF p_verification_method NOT IN ('phone_otp', 'institutional_email_otp', 'qr', 'eid') THEN
      RAISE EXCEPTION 'VP_INVALID_VERIFICATION_METHOD' USING ERRCODE = 'P0001';
    END IF;

    INSERT INTO adhesions (
      protest_id, device_id, phone_hash, identity_subject_hash, verification_method,
      doc_hash, ciudad, region, pais, pais_code, idioma, nullifier, created_at,
      fiabilidad, senales, gps_confirmed, adhesion_osm_id
    ) VALUES (
      p_protest_id, p_device_id, p_identity_subject_hash, p_identity_subject_hash, p_verification_method,
      p_doc_hash, p_ciudad, p_region, p_pais, p_pais_code, p_idioma, p_nullifier, v_created_at,
      p_fiabilidad, p_senales, p_gps_confirmed, p_adhesion_osm_id
    )
    RETURNING id INTO v_adhesion_id;
  EXCEPTION
    WHEN unique_violation THEN
      DECLARE
        v_constraint text;
      BEGIN
        GET STACKED DIAGNOSTICS v_constraint = CONSTRAINT_NAME;
        IF v_constraint IN ('adhesions_active_nullifier_unique', 'adhesions_active_device_unique') THEN
          RAISE EXCEPTION 'VP_ALREADY_JOINED' USING ERRCODE = 'P0001';
        ELSIF v_constraint = 'institutional_member_unique' THEN
          RAISE EXCEPTION 'VP_MEMBERSHIP_ALREADY_EXISTS' USING ERRCODE = 'P0001';
        ELSE
          RAISE;
        END IF;
      END;
  END;

  UPDATE protests SET count = count + 1 WHERE id = p_protest_id;
  PERFORM update_cities_count(p_protest_id);

  IF p_device_id IS NOT NULL THEN
    UPDATE devices SET last_seen = now() WHERE id = p_device_id;
  END IF;

  RETURN jsonb_build_object(
    'id', v_adhesion_id, 'created_at', v_created_at,
    'ciudad', p_ciudad, 'region', p_region, 'pais', p_pais,
    'adhesion_osm_id', p_adhesion_osm_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.verify_census_founder_adhesion(p_email_hash text, p_protest_id uuid, p_submitted_otp_hash text, p_identity_subject_hash text, p_nullifier text, p_ciudad text, p_region text, p_pais text, p_pais_code text, p_idioma text, p_institutional_expires_at timestamp with time zone, p_creator_key_hash text, p_challenge_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE p public.protests%ROWTYPE; proof voiceprotest_private.census_creator_proofs%ROWTYPE; result jsonb;
BEGIN
 SELECT * INTO p FROM public.protests WHERE id=p_protest_id FOR UPDATE;
 SELECT * INTO proof FROM voiceprotest_private.census_creator_proofs WHERE protest_id=p.id FOR UPDATE;
 IF p_email_hash IS DISTINCT FROM p_identity_subject_hash OR NOT p.requiere_censo OR p.ends_at<=now()
  OR proof.used_at IS NOT NULL OR proof.key_hash IS NULL OR proof.key_hash IS DISTINCT FROM p_creator_key_hash
  OR (proof.founder_hash IS NOT NULL AND proof.founder_hash IS DISTINCT FROM p_email_hash)
  OR EXISTS(SELECT 1 FROM public.groups WHERE protest_id=p_protest_id)
 THEN RAISE EXCEPTION 'CREATOR_PROOF_REQUIRED'; END IF;
 PERFORM set_config('voiceprotest.creator_proof',p_creator_key_hash,true);
 result:=public.verify_institutional_challenge_and_create_adhesion(p_email_hash,p_protest_id,p_submitted_otp_hash,p_identity_subject_hash,p_nullifier,p_ciudad,p_region,p_pais,p_pais_code,p_idioma,p_institutional_expires_at,p_challenge_id);
 IF NOT result ? 'error' THEN UPDATE voiceprotest_private.census_creator_proofs SET founder_hash=p_email_hash WHERE protest_id=p.id; END IF;
 PERFORM set_config('voiceprotest.creator_proof','',true);
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.verify_institutional_challenge_and_create_adhesion(p_email_hash text, p_protest_id uuid, p_submitted_otp_hash text, p_identity_subject_hash text, p_nullifier text, p_ciudad text, p_region text, p_pais text, p_pais_code text, p_idioma text, p_institutional_expires_at timestamp with time zone, p_challenge_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE
  v_otp record;
  v_result jsonb;
BEGIN
  IF p_email_hash IS DISTINCT FROM p_identity_subject_hash THEN RAISE EXCEPTION 'IDENTITY_MISMATCH'; END IF;
  SELECT id, otp_hash, expires_at, consumed_at, attempt_count
    INTO v_otp
    FROM public.email_otp_requests
    WHERE id=p_challenge_id AND email_hash = p_email_hash AND protest_id = p_protest_id
    FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'VP_OTP_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;

  IF v_otp.consumed_at IS NOT NULL THEN
    RAISE EXCEPTION 'VP_OTP_ALREADY_USED' USING ERRCODE = 'P0001';
  END IF;

  IF v_otp.expires_at IS NULL OR v_otp.expires_at <= now() THEN
    RAISE EXCEPTION 'VP_OTP_EXPIRED' USING ERRCODE = 'P0001';
  END IF;

  -- VP-SEC-014: failed attempts are counted transactionally against this
  -- specific request row, not left to an in-memory or per-process limiter
  -- alone. After 5 wrong codes the row is dead regardless of whether it has
  -- technically expired yet.
  IF v_otp.attempt_count >= 5 THEN
    RAISE EXCEPTION 'VP_TOO_MANY_ATTEMPTS' USING ERRCODE = 'P0001';
  END IF;

  IF v_otp.otp_hash IS DISTINCT FROM p_submitted_otp_hash THEN
    UPDATE public.email_otp_requests SET attempt_count = attempt_count + 1 WHERE id = v_otp.id;
    RETURN jsonb_build_object('error','VP_WRONG_OTP');
  END IF;

  -- Consume now, before creating the adhesion — if create_verified_adhesion
  -- below raises, this UPDATE rolls back together with it (same
  -- transaction), so a failed adhesion never leaves the OTP burned.
  UPDATE public.email_otp_requests SET consumed_at = now() WHERE id = v_otp.id;

  v_result := public.create_verified_adhesion(
    p_protest_id               => p_protest_id,
    p_identity_subject_hash    => p_identity_subject_hash,
    p_verification_method      => 'institutional_email_otp',
    p_nullifier                => p_nullifier,
    p_device_id                => NULL,
    p_doc_hash                 => NULL,
    p_ciudad                   => p_ciudad,
    p_region                   => p_region,
    p_pais                     => p_pais,
    p_pais_code                => p_pais_code,
    p_idioma                   => p_idioma,
    p_adhesion_osm_id          => NULL,
    p_gps_confirmed            => false,
    p_fiabilidad               => 90,
    p_senales                  => 'email_otp,ip',
    p_institutional_email_hash => p_email_hash,
    p_institutional_expires_at => p_institutional_expires_at
  );

  RETURN v_result;
END;
$function$
